/* ---- 任务栏 / 空态 ---- */
function deskBarRender() {
  const list = $("deskList");
  if (!list) return;
  list.innerHTML = "";
  const arr = Array.from(DESK.wins.values()).sort((a, b) => a.id - b.id);
  for (const w of arr) {
    const b = document.createElement("button");
    b.className = "db-item" + ((w.id === DESK.focus && !w.min) ? " on" : "") + (w.min ? " min" : "");
    b.title = (w.title || ("窗口 " + w.id)) + (w.sub ? " · " + w.sub : "") + "（右键关闭）";
    const ico = document.createElement("span");
    ico.className = "db-ico"; ico.textContent = deskInitial(w.title || ("窗口 " + w.id));
    const nm = document.createElement("span");
    nm.className = "db-name"; nm.textContent = w.title || ("窗口 " + w.id);
    b.appendChild(ico); b.appendChild(nm);
    b.onclick = () => deskFocus(w.id);
    b.oncontextmenu = e => { e.preventDefault(); deskCloseWin(w.id); };
    list.appendChild(b);
  }
  const tag = $("deskTag");
  if (tag) tag.textContent = (DESK.displayId ? "D" + DESK.displayId + " · " : "") + "窗口 " + DESK.wins.size + " / 应用 " + DESK.tasks.length;
  deskUpdateEmpty();
}
function deskUpdateEmpty() {
  const el = $("deskEmpty");
  if (!el) return;
  const empty = DESK.wins.size === 0;
  el.classList.toggle("hide", !empty);
  if (empty) el.innerHTML = "副屏暂无已开应用<br>在手机上把应用拉到虚拟屏后点「刷新」（不提供假的开应用入口）";
}

/* ---- 与 /api/desktop/windows 对账（逐窗口：一个应用 = 一张虚拟屏 + 一路独立流） ----
 * 客户端窗口 id **直接采用服务端 windowId**：0x11 帧按 windowId 复用，于是每帧天然
 * 落到它自己的窗口，无需任何映射表。窗口重建（resize/close）由服务端负责释放 VD。 */
async function deskSyncTasks(opts) {
  opts = opts || {};
  DESK.lastSyncTs = performance.now();
  let res = null;
  try {
    const r = await fetch(apiUrl("api/desktop/windows"), { cache: "no-store" });
    if (r.ok) res = await r.json().catch(() => null);
  } catch (e) { res = null; }
  if (!res || res.ok !== true || !Array.isArray(res.windows)) return false;
  const wins = res.windows.filter(w => w && typeof w.windowId === "number" && w.windowId > 0 && w.state === "running");
  DESK.tasks = wins;
  const byId = new Map(wins.map(w => [w.windowId, w]));

  // 回收：客户端有（服务端托管）、服务端已没有的窗口 → 本地移除（服务端已释放 VD/采集）。
  Array.from(DESK.wins.values()).forEach(w => {
    if (w.server && w.id > 0 && !byId.has(w.id)) deskRemoveWin(w.id, true);
  });
  for (const s of wins) {
    let w = DESK.wins.get(s.windowId);
    if (!w) {
      w = deskNewWin({ id: s.windowId, kind: "app", srcW: s.width, srcH: s.height });
      if (!w) continue;
    }
    w.server = true;
    w.taskId = (typeof s.taskId === "number" ? s.taskId : 0);
    w.kind = "app";
    if (s.width > 0) w.srcW = s.width;
    if (s.height > 0) w.srcH = s.height;
    w.title = deskAppName(s.packageName);
    w.sub = (s.packageName || "") + " #" + s.windowId +
      ((s.width && s.height) ? (" · " + s.width + "×" + s.height) : "");
    deskUpdateWinChrome(w);
  }
  // 有应用窗口了就撤掉「桌面」占位窗（它只是没应用时活画面的落脚点）
  if (wins.length) {
    Array.from(DESK.wins.values()).forEach(w => { if (w.kind === "desk" && !w.taskId && !w.server) deskRemoveWin(w.id, true); });
  }
  if (!DESK.wins.size) deskNewWin({ id: 0, kind: "desk", title: "桌面", sub: "整屏流" });

  if (!DESK.wins.has(DESK.focus)) {
    const pick = DESK.wins.values().next().value || null;
    if (pick) deskFocus(pick.id, { noSwitch: true });
  }
  // 应用窗口集合或源几何变了 → 重新并排平铺：两个窗口必须同时可见、各按原生几何。
  const sig = wins.map(w => w.windowId + ":" + (w.width | 0) + "x" + (w.height | 0)).join(",");
  if (sig !== DESK.appSig) { DESK.appSig = sig; deskLayoutApps(); }
  deskBarRender(); deskSyncCanvasHost(); fitCanvas();
  return true;
}

/* ---- 打开一个应用到独立窗口（POST /api/desktop/windows open） ---- */
async function deskOpenApp(pkg) {
  if (!pkg) return false;
  try {
    const r = await fetch(apiUrl("api/desktop/windows"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "open", package: pkg }), // 几何用服务端默认（不传 = 720×1280）
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.ok) { toast("已打开 " + deskAppName(pkg), 2400); setTimeout(deskSyncTasks, 500); return true; }
    toast("打开失败：" + (j.error || ("HTTP " + r.status)), 4600);
    return false;
  } catch (e) { toast("打开失败：请求失败", 4600); return false; }
}

/* ---- 打开应用选择器（GET /api/apps → 可启动应用列表） ---- */
let APPS_CACHE = null;
function deskRenderAppList(q) {
  const list = $("appList");
  if (!list) return;
  list.innerHTML = "";
  const apps = (APPS_CACHE || []).filter(a => !q ||
    String(a.label || "").toLowerCase().includes(q) || String(a.package || "").toLowerCase().includes(q));
  if (!apps.length) { list.innerHTML = '<p style="font-size:12px;color:var(--muted)">没有匹配的应用</p>'; return; }
  for (const a of apps.slice(0, 300)) {
    const b = document.createElement("button");
    b.className = "db-item"; b.style.textAlign = "left";
    const ico = document.createElement("span"); ico.className = "db-ico";
    ico.textContent = deskInitial(a.label || a.package);
    const nm = document.createElement("span"); nm.className = "db-name";
    nm.textContent = (a.label || a.package) + "  " + (a.package || "");
    b.appendChild(ico); b.appendChild(nm);
    b.onclick = () => { $("appPicker").classList.add("hide"); deskOpenApp(a.package); };
    list.appendChild(b);
  }
}
async function deskOpenAppPicker() {
  $("appPicker").classList.remove("hide");
  $("appSearch").value = "";
  if (!APPS_CACHE) {
    $("appList").innerHTML = '<p style="font-size:12px;color:var(--muted)">正在读取应用列表…</p>';
    try {
      const r = await fetch(apiUrl("api/apps"), { cache: "no-store" });
      const j = await r.json().catch(() => null);
      APPS_CACHE = (j && Array.isArray(j.apps)) ? j.apps : [];
    } catch (e) { APPS_CACHE = []; }
  }
  deskRenderAppList("");
}
function deskMaybeSyncTasks() {
  if (!DESK.on) return;
  if (performance.now() - DESK.lastSyncTs < 9000) return;
  deskSyncTasks();
}

/* ---- 进 / 出桌面外壳 ---- */
function deskEnter(info) {
  if (!DESK.on) {
    DESK.on = true;
    DESK.focus = -1;
    DESK.missCount = 0;
    document.body.classList.add("desk");
    $("deskShell").classList.remove("hide");
    deskApplyScale();
    const a = $("deskArea");
    DESK.areaW = a.clientWidth; DESK.areaH = a.clientHeight;
    deskStatusHide();
    toast("🖥 已进入 Fusion 独立桌面" + (info && info.displayId > 0 ? " (D" + info.displayId + ")" : ""), 3200);
  }
  DESK.displayId = (info && info.displayId > 0) ? info.displayId : 0;
  deskSyncTasks({ initial: true });
  deskBarRender();
}
function deskExit() {
  if (!DESK.on) return;
  DESK.on = false;
  document.body.classList.remove("desk");
  DESK.drag = null;
  Array.from(DESK.wins.keys()).forEach(id => deskRemoveWin(id, true));
  $("deskShell").classList.add("hide");
  deskStatusHide();
  syncMirrorHost();
  DESK.focus = -1;
  ensureMirrorStream(); // 桌面用自己那路 VDM 源，物理镜像采集多半没在跑：主动唤醒，别切回来黑屏
}
/**
 * 切回镜像后确保**物理采集**在跑。
 * 桌面模式下采集走的是各窗自己的 VDM 源，物理镜像的 0x01 源可能从没起来；不主动
 * 唤醒就会出现「切回镜像一片黑」。已有会话时只唤醒采集，不强行重连（避免闪断）。
 */
async function ensureMirrorStream() {
  try {
    const st = await queryStreaming();
    if (st === false) {
      showBoot(STREAM_WAKE_MSG);
      const ok = await wakeStreaming();
      if (ok === false) { showStreamOff(); return; }
    }
    hideStreamOffRestore();
    hideBoot();
    if (!S.connected) connect();
  } catch (e) { /* 唤醒失败也别抛，保留兜底遮罩 */ }
}
function deskFallbackMirror(reason) {
  const was = DESK.on;
  deskExit();
  // 启动失败时壳从没亮过（was=false），也得给一句可读的提示，不能静默
  if (was || reason) toast("已回退物理屏镜像：" + (reason || "桌面已关闭"), 4200);
  DESK.lastError = reason || "";
}
function deskOnResize() {
  if (!DESK.on) return;
  deskApplyScale();
  const a = $("deskArea");
  const W = a.clientWidth, H = a.clientHeight;
  if (!W || !H) return;
  if (DESK.areaW && DESK.areaH && (Math.abs(W - DESK.areaW) > 2 || Math.abs(H - DESK.areaH) > 2)) {
    const kx = W / DESK.areaW, ky = H / DESK.areaH;
    DESK.wins.forEach(w => {
      if (w.max) deskPlace(w, { x: 0, y: 0, w: W, h: H });
      else deskPlace(w, { x: w.x * kx, y: w.y * ky, w: w.w * kx, h: w.h * ky });
    });
  }
  DESK.areaW = W; DESK.areaH = H;
  fitCanvas();
}

/* ---- 壳内状态卡（启动中 / 断流 / 停采） ---- */
function deskStatusShow(msg, kind) {
  DESK.statusKind = kind || "";
  const el = $("deskStatusMsg");
  if (el) el.textContent = msg;
  $("deskStatus").classList.remove("hide");
}
function deskStatusHide() {
  DESK.statusKind = "";
  const el = $("deskStatus");
  if (el) el.classList.add("hide");
}
function deskStreamLost() {
  if (DESK.streamTimer) return;
  if (DESK.streamTry >= 5) {
    deskStatusShow("推流中断，已自动重连 5 次仍未恢复。点「重试」再连一次，或先切回镜像。", "error");
    return;
  }
  const n = ++DESK.streamTry;
  deskStatusShow("推流中断，正在自动重连…（第 " + n + " 次）", "retry");
  DESK.streamTimer = setTimeout(() => { DESK.streamTimer = 0; connect(); }, 1500);
}
function deskStreamUp() {
  if (DESK.streamTimer) { clearTimeout(DESK.streamTimer); DESK.streamTimer = 0; }
  DESK.streamTry = 0;
  if (DESK.statusKind === "retry" || DESK.statusKind === "boot") deskStatusHide();
}

/* ---- 启动桌面模式（默认路径） ---- */
async function deskEnsureOn(ms) {
  let last = null;
  try {
    const r = await fetch(apiUrl("api/desktop"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "on" }),
    });
    last = await r.json().catch(() => null);
    if (r.ok && isDeskOn(last)) return last;
    if (last && last.error) DESK.lastError = last.error;
  } catch (e) { DESK.lastError = "请求失败"; }
  const deadline = Date.now() + ms;
  let fails = 0;
  while (Date.now() < deadline) {
    await new Promise(r => setTimeout(r, 600));
    const j = await queryDesktop();
    if (j) { last = j; fails = 0; if (isDeskOn(j)) return j; if (j.error) DESK.lastError = j.error; }
    else if (++fails >= 3) break;
  }
  return last;
}
/* 打开控制台后的默认路径：能进桌面就进桌面；服务端不支持 / 起不来就留在镜像（绝不黑屏卡死）。 */
async function desktopAutoEnter() {
  const info = await queryDesktop();
  if (info === null) return;                 // 老服务端没有 /api/desktop：镜像照旧，不打扰
  if (isDeskOn(info)) { deskEnter(info); return; }
  if (deskPrefGet() === "mirror") return;    // 用户明确选过镜像：刷新后不硬拉回桌面
  deskStatusShow("正在启动独立桌面…", "boot");
  const j = await deskEnsureOn(9000);
  if (isDeskOn(j)) { deskStatusHide(); deskEnter(j); return; }
  deskStatusHide();
  deskFallbackMirror(DESK.lastError || "独立桌面 9s 内未起来");
}

/* ---- 交互绑定 ---- */
function deskBindWin(win) {
  const bar = win.bar;
  bar.addEventListener("pointerdown", e => {
    if (e.target && e.target.closest && e.target.closest(".dw-btn")) return;
    if (e.button !== 0) return;
    e.preventDefault();
    deskFocus(win.id);
    if (win.max) deskToggleMax(win); // 最大化状态拖动先还原成窗口
    DESK.drag = { win: win, pid: e.pointerId, sx: e.clientX, sy: e.clientY, x0: win.x, y0: win.y };
    try { bar.setPointerCapture(e.pointerId); } catch (x) {}
  });
  bar.addEventListener("pointermove", e => {
    const d = DESK.drag;
    if (!d || d.win !== win || d.pid !== e.pointerId) return;
    deskPlace(win, { x: d.x0 + (e.clientX - d.sx), y: d.y0 + (e.clientY - d.sy) });
  });
  const endDragWin = e => {
    const d = DESK.drag;
    if (!d || d.win !== win || d.pid !== e.pointerId) return;
    DESK.drag = null;
    try { bar.releasePointerCapture(e.pointerId); } catch (x) {}
  };
  bar.addEventListener("pointerup", endDragWin);
  bar.addEventListener("pointercancel", endDragWin);

  const b = sel => win.el.querySelector(sel);
  // 左侧交通灯：红=关闭 / 琥珀=最小化 / 绿=最大化（macOS 语义，对齐用户截图）。
  b(".tl-close").addEventListener("click", e => { e.stopPropagation(); deskCloseWin(win.id); });
  b(".tl-min").addEventListener("click", e => { e.stopPropagation(); deskMinimize(win.id); });
  b(".tl-max").addEventListener("click", e => { e.stopPropagation(); deskToggleMax(win); });
  // 右侧：‹ 返回（注入 Back，落到本窗口自己的屏）/ ⋮ 菜单。
  b(".dw-back").addEventListener("click", e => {
    e.stopPropagation(); deskFocus(win.id);
    sendCtl({ type: "click", button: "right", wid: widOf(win.el) });
  });
  b(".dw-menu").addEventListener("click", e => { e.stopPropagation(); deskWinMenu(win); });
  win.el.addEventListener("pointerdown", () => deskFocus(win.id), true); // 点哪都先聚焦（含内容区）
}
/** 窗口 ⋮ 菜单：全部动作都带 wid，落到该窗口自己的虚拟屏，绝不碰别的窗口或物理主屏。 */
function deskWinMenu(win) {
  const old = win.el.querySelector(".dw-pop");
  if (old) { old.remove(); return; }
  const pop = document.createElement("div");
  pop.className = "dw-pop";
  pop.addEventListener("pointerdown", e => e.stopPropagation()); // 别触发标题栏拖拽
  const items = [
    ["返回", () => sendCtl({ type: "click", button: "right", wid: win.id })],
    ["回到主屏", () => sendCtl({ type: "click", button: "middle", wid: win.id })],
    ["最近任务", () => sendCtl({ type: "key", keycode: 187, wid: win.id })],
    ["重新请求关键帧", () => requestKeyframe(win.id)],
    ["关闭窗口", () => deskCloseWin(win.id)],
  ];
  for (const [label, fn] of items) {
    const btn = document.createElement("button");
    btn.textContent = label;
    btn.onclick = e => { e.stopPropagation(); pop.remove(); fn(); };
    pop.appendChild(btn);
  }
  win.bar.appendChild(pop);
  setTimeout(() => document.addEventListener("pointerdown", function off() {
    document.removeEventListener("pointerdown", off);
    try { pop.remove(); } catch (e) {}
  }, { once: true }), 0);
}

/* ---- 逐窗口视频（0x11）：优先用并行解码模块 H264Player，无模块退回旧 VideoDecoder ---- */
/**
 * 为该窗口建/取解码播放器（Phase E 模块，普通 LAN HTTP 也能硬解）。
 *
 * 模块自带渲染面（安全上下文 <canvas>，非安全上下文 <video>），把它当该窗口的
 * 画面元素与输入面：置 win.cv = p.element，于是 inputSurface()/widOf() 天然把它
 * 当成该窗口的输入面，归一化坐标不变。返回 false = 模块不可用（退回旧 VideoDecoder）。
 */
function winEnsurePlayer(win) {
  if (!win) return false;
  if (win.player) return true;
  if (typeof H264Player === "undefined" || !H264Player.create) return false;
  try {
    const p = H264Player.create({
      container: win.body,
      backend: "auto",
      maxLatencyMs: 300,
      // 解码器要 IDR（丢帧/换源）→ 让服务端对**这一路**立刻补一个关键帧。
      onNeedKeyframe: () => { try { requestKeyframe(win.id); } catch (e) {} },
      onFrame: () => { S.fpsCount++; },
      onResize: (w, h) => { win.srcW = w; win.srcH = h; try { deskLayoutApps(); } catch (e) {} },
      onError: e => { try { console.warn("[H264Player win " + win.id + "]", e); } catch (x) {} },
    });
    win.player = p;
    const el = p.element;
    if (el) {
      el.className = "dw-cv"; el.tabIndex = 0;
      if (win.cv && win.cv !== el) { try { win.cv.style.display = "none"; } catch (e) {} }
      win.cv = el; win.ctx = null;
      bindInputSurface(el);
    }
    win.hasOwnStream = true;
    return true;
  } catch (e) { console.warn("[H264Player create win " + win.id + "]", e); win.player = null; return false; }
}
function winDropPlayer(win) {
  if (!win || !win.player) return;
  try { win.player.close(); } catch (e) {}
  win.player = null;
}
/** 0x11 负载里 8 字节大端 pts（微秒）。>2^53 不可能（µs 时钟），安全。 */
function readPtsUs(u8, off) {
  let v = 0;
  for (let i = 0; i < 8; i++) v = v * 256 + u8[off + i];
  return v;
}
/** 扫 Annex-B 里的 IDR（NAL type 5）；给模块一个明确的关键帧提示。 */
function scanKeyframe(nalu) {
  const nalus = splitAnnexB(nalu);
  for (const n of nalus) if ((nalu[n.hdr] & 0x1F) === 5) return true;
  return undefined;
}
function winEnsureDecoder(win) {
  if (typeof VideoDecoder === "undefined") return false;
  if (!win.sps || !win.pps || win.sps.length < 4) return false;
  const key = win.sps.length + ":" + win.sps[1] + "," + win.sps[2] + "," + win.sps[3];
  if (win.dec && win.dec.state !== "closed" && win.decKey === key &&
      eqBytes(win.sps, win._sps) && eqBytes(win.pps, win._pps)) return true;
  try { if (win.dec) win.dec.close(); } catch (e) {}
  win.dec = null; win.hasKey = false;
  try {
    const dec = new VideoDecoder({
      output: f => queueFrame(win, f),
      error: e => console.warn("[vdec win " + win.id + "]", e),
    });
    dec.configure({
      codec: "avc1." + hex(win.sps[1]) + hex(win.sps[2]) + hex(win.sps[3]),
      description: buildAvcC(win.sps, win.pps), optimizeForLatency: true,
    });
    win.dec = dec; win.decKey = key;
    win._sps = win.sps.slice(); win._pps = win.pps.slice();
    return true;
  } catch (e) { console.warn("[vdec win " + win.id + " configure]", e); return false; }
}
function winDropDecoder(win) {
  if (!win) return;
  winDropPlayer(win); // 释放模块：移除渲染面 + 关 MSE/解码器
  try { if (win.dec) win.dec.close(); } catch (e) {}
  win.dec = null; win.decKey = ""; win.hasKey = false;
  win.sps = win.pps = win._sps = win._pps = null;
}
function winDecode(win, payload) {
  const nalus = splitAnnexB(payload);
  if (!nalus.length) return;
  let hasIdr = false, dirty = false;
  for (const n of nalus) {
    const t = payload[n.hdr] & 0x1F;
    if (t === 7) { const b = payload.slice(n.hdr, n.end); if (!eqBytes(b, win.sps)) { win.sps = b; dirty = true; } }
    else if (t === 8) { const b = payload.slice(n.hdr, n.end); if (!eqBytes(b, win.pps)) { win.pps = b; dirty = true; } }
    else if (t === 5) hasIdr = true;
  }
  if (dirty || !win.dec || win.dec.state === "closed") { if (!winEnsureDecoder(win)) return; }
  if (!win.dec || (win.dec.state !== "playing" && win.dec.state !== "configured")) { if (!winEnsureDecoder(win)) return; }
  if (!hasIdr && !win.hasKey) return;
  if (win.dec.decodeQueueSize > 4 && !hasIdr) return;
  let total = 0;
  for (const n of nalus) total += 4 + (n.end - n.hdr);
  const mp4 = new Uint8Array(total);
  let o = 0;
  for (const n of nalus) {
    const len = n.end - n.hdr;
    mp4[o++] = (len >>> 24) & 0xFF; mp4[o++] = (len >>> 16) & 0xFF;
    mp4[o++] = (len >>> 8) & 0xFF; mp4[o++] = len & 0xFF;
    mp4.set(payload.subarray(n.hdr, n.end), o); o += len;
  }
  const wall = performance.now() * 1000;
  win.ts = Math.max(wall, win.lastTs + 1); win.lastTs = win.ts;
  try {
    win.dec.decode(new EncodedVideoChunk({ type: (hasIdr || !win.hasKey) ? "key" : "delta", timestamp: Math.round(win.ts), data: mp4 }));
    if (hasIdr) win.hasKey = true;
  } catch (e) { /* 坏帧丢弃，等 I 帧自愈 */ }
}
/* 通道 0x11 负载：[1字节 windowId][8字节大端 pts(微秒)][H.264 Annex-B…]。
 * 一窗一路独立流：每个窗口喂自己的 H264Player（普通 http 走 MSE，安全上下文走 WebCodecs）。 */
function feedWindowVideo(payload) {
  if (!payload || payload.length < 10) return; // 1 wid + 8 pts + 至少 1 字节 NALU
  const wid = payload[0];
  const ptsUs = readPtsUs(payload, 1);
  const nalu = payload.subarray(9);
  if (wid === 0) { feedVideo(nalu); return; } // 0 = 整屏流那一路，并回主画面
  let win = DESK.wins.get(wid);
  if (!win) {
    if (!DESK.on) return; // 没在桌面模式就先忽略，别凭空造壳
    win = deskNewWin({ id: wid, kind: "auto", title: "窗口 " + wid, sub: "服务端逐窗口流" });
    if (!win) return;
    deskUpdateWinChrome(win);
    deskBarRender();
    if (DESK.focus < 0) deskFocus(win.id, { noSwitch: true });
  }
  winFeed(win, nalu, ptsUs);
}
/** 喂一帧给窗口：优先模块（H264Player），无模块退回旧 VideoDecoder 路。 */
function winFeed(win, nalu, ptsUs) {
  if (winEnsurePlayer(win)) {
    try { win.player.pushAnnexB(nalu, (ptsUs > 0 ? ptsUs : undefined), scanKeyframe(nalu)); } catch (e) {}
    return;
  }
  winDecode(win, nalu);
}

/* ---- 外壳按钮 ---- */
$("deskOpen").onclick = () => deskOpenAppPicker();
$("btnAppClose").onclick = () => $("appPicker").classList.add("hide");
$("appSearch").oninput = () => deskRenderAppList($("appSearch").value.trim().toLowerCase());
$("deskRefresh").onclick = () => { toast("正在刷新窗口列表…", 1200); deskSyncTasks(); };
$("deskToMirror").onclick = () => { toggleDesktop(); };
$("deskStatusMirror").onclick = () => { deskStatusHide(); toggleDesktop(); };
$("deskStatusRetry").onclick = async () => {
  deskStatusHide();
  try {
    await fetch(apiUrl("api/stream"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "on" }),
    });
  } catch (e) {}
  connect(); startStatusPoll(); pollStatus();
};

/* ---- 故障提示条 ----
 * 只在对用户**有实际影响**时才出现（例：H264 硬解不可用、已降级 JPEG）。
 * 「非安全上下文」本身不再是提示理由：局域网 http 下已走 MSE 播 H.264，体验正常；
 * 后端/画质细节放状态详情与报告，不打扰用户。 */
function secBannerShow(msg) {
  const el = $("secBanner");
  if (!el) return;
  if (msg) { const s = el.querySelector("span"); if (s) s.textContent = msg; }
  el.classList.remove("hide");
}
function secBannerHide() { const el = $("secBanner"); if (el) el.classList.add("hide"); }
$("secBannerX").onclick = () => secBannerHide();

/* FPS 统计 + 逐窗口流自愈 */
setInterval(() => {
  $("pillFps").textContent = "FPS " + S.fpsCount;
  $("pillFps").className = "pill " + (S.fpsCount > 0 ? "ok" : "");
  S.fpsCount = 0;
  // 自愈：桌面里某窗口还没出画就每秒主动要一个该窗口的 IDR。
  // 起因（真机实测）：切镜像回来 / 断流重连后，服务端补发的关键帧可能早于客户端进桌面被丢掉，
  // 而静态应用（Settings）此后不再出帧 → 永久停在「正在等待该窗口的独立视频流…」。
  if (DESK.on) {
    DESK.wins.forEach(w => {
      if (w.server && w.id > 0 && !w.hasOwnStream) {
        w.healTries = (w.healTries || 0) + 1;
        if (w.healTries <= 20) { try { requestKeyframe(w.id); } catch (e) {} } // 上限 20 次，避免死窗空转
      }
    });
  }
}, 1000);

/* ---------------- 反向操控输入 ----------------
 * 输入面 = 当前聚焦窗口里那块「画布即画面」（桌面模式）或 #canvas（镜像模式）。
 * 画布矩形就是 display 上那块区域，所以归一化坐标一路不变，control 协议无需改动。 */
function inputSurface(e) {
  const el = e && e.currentTarget;
  // 输入面可能是 <canvas>（模块 webcodecs 后端 / 旧路窗口画布）或 <video>（模块 MSE 后端）：
  // 都按「事件源即输入面」处理，矩形直接就是画面矩形，归一化坐标一路不变。
  if (el && (el.tagName === "CANVAS" || el.tagName === "VIDEO")) return el;
  const f = DESK.on ? DESK.wins.get(DESK.focus) : null;
  if (f && f.hasOwnStream && f.cv) return f.cv;
  return canvas;
}
/**
 * 输入面所属窗口 id（0 = 整屏桌面源 / 物理镜像路）。
 *
 * 一窗一路流之后，注入目标必须按**窗口**选屏：控制协议的 `wid` 由服务端翻成该窗口
 * 自己的 displayId，输入才不会落到别的窗口或物理主屏。判定用 DOM 归属
 * （`.desk-win[data-wid]`），不依赖任何全局「当前焦点」状态——焦点与事件源可能不同步。
 */
function widOf(el) {
  if (!el || !el.closest) return 0;
  const host = el.closest(".desk-win");
  if (!host) return 0;
  const n = parseInt(host.dataset.wid, 10);
  return (Number.isFinite(n) && n > 0) ? n : 0;
}
/** 键盘 / 文本注入的落点窗口：聚焦窗口的流（0 = 整屏路）。 */
function focusWid() {
  const f = DESK.on ? DESK.wins.get(DESK.focus) : null;
  return (f && f.id > 0) ? f.id : 0;
}
function normPos(e) {
  const r = inputSurface(e).getBoundingClientRect();
  if (!r.width || !r.height) return { x: 0.5, y: 0.5 };
  return { x: clamp01((e.clientX - r.left) / r.width), y: clamp01((e.clientY - r.top) / r.height) };
}
function bindInputSurface(el) {
  // 本输入面所有上行控制消息都带上归属窗口 id（0 = 整屏路）。
  const ctl = obj => { obj.wid = widOf(el); return sendCtl(obj); };
  el.addEventListener("contextmenu", e => e.preventDefault());
  el.addEventListener("mousedown", e => { if (e.button === 1) e.preventDefault(); }); // 拦截中键自动滚动
  el.addEventListener("auxclick", e => e.preventDefault());

  el.addEventListener("pointerdown", e => {
    ensureActx();
    try { el.focus(); } catch (x) {}
    if (e.button === 2) { ctl({ type: "click", button: "right" }); return; } // 右键=返回
    if (e.button === 1) { ctl({ type: "click", button: "middle" }); return; } // 中键=Home
    if (e.button !== 0) return;
    const p = normPos(e);
    S.dragging = true;
    try { el.setPointerCapture(e.pointerId); } catch (x) {}
    ctl({ type: "down", x: +p.x.toFixed(4), y: +p.y.toFixed(4) });
  });
  el.addEventListener("pointermove", e => {
    if (!S.dragging || e.buttons === 0 && e.pointerType === "mouse") return;
    const now = performance.now();
    if (now - S.lastMoveTs < 16) return; // ~60Hz节流
    S.lastMoveTs = now;
    const p = normPos(e);
    ctl({ type: "move", x: +p.x.toFixed(4), y: +p.y.toFixed(4) });
  });
  el.addEventListener("pointerup", e => endDrag(e, el));
  el.addEventListener("pointercancel", () => { if (S.dragging) { S.dragging = false; ctl({ type: "up", x: 0.5, y: 0.5 }); } });

  /* 滚轮 = 定向滑动 */
  el.addEventListener("wheel", e => {
    e.preventDefault();
    const horiz = Math.abs(e.deltaX) > Math.abs(e.deltaY);
    const d = horiz ? e.deltaX : e.deltaY;
    if (!d) return;
    const r = el.getBoundingClientRect();
    const rangePx = Math.min(220, Math.max(80, (horiz ? r.width : r.height) * 0.25));
    const sign = d > 0 ? 1 : -1;
    const p = normPos(e);
    let x0 = p.x, y0 = p.y, x1 = p.x, y1 = p.y;
    if (horiz) { const s = rangePx / r.width / 2; x0 = clamp01(p.x + s * sign); x1 = clamp01(p.x - s * sign); }
    else { const s = rangePx / r.height / 2; y0 = clamp01(p.y + s * sign); y1 = clamp01(p.y - s * sign); }
    ctl({ type: "down", x: +x0.toFixed(4), y: +y0.toFixed(4) });
    const steps = 3;
    for (let i = 1; i <= steps; i++) {
      setTimeout(((xx, yy) => () => ctl({ type: "move", x: +xx.toFixed(4), y: +yy.toFixed(4) }))
        (x0 + (x1 - x0) * i / steps, y0 + (y1 - y0) * i / steps), i * 18);
    }
    setTimeout(() => ctl({ type: "up", x: +x1.toFixed(4), y: +y1.toFixed(4) }), (steps + 1) * 18);
  }, { passive: false });
}
function endDrag(e, el) {
  if (!S.dragging) return;
  S.dragging = false;
  if (e && e.button !== undefined && e.button !== 0) return;
  const p = e ? normPos(e) : { x: 0.5, y: 0.5 };
  const src = el || inputSurface(e);
  sendCtl({ type: "up", wid: widOf(src), x: +p.x.toFixed(4), y: +p.y.toFixed(4) });
}
bindInputSurface(canvas);

/* 键盘: 可打印字符走text批量注入, 功能键走key */
const KEYMAP = {
  Enter: 66, Backspace: 67, Escape: 4, Tab: 61,
  ArrowUp: 19, ArrowDown: 20, ArrowLeft: 21, ArrowRight: 22,
  Home: 3, End: 123, PageUp: 92, PageDown: 93, Delete: 112,
};
function flushText() {
  if (!S.textBuf) return;
  const t = S.textBuf; S.textBuf = "";
  sendCtl({ type: "text", wid: focusWid(), text: t });
}
document.addEventListener("keydown", e => {
  if (!$("authOverlay").classList.contains("hide")) return; // 鉴权框内不拦截
  const tag = (e.target && e.target.tagName) || "";
  if (tag === "INPUT" || tag === "TEXTAREA") return;
  if (!S.connected) return;
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key.length === 1) {
    S.textBuf += e.key;
    if (S.textTimer) clearTimeout(S.textTimer);
    S.textTimer = setTimeout(flushText, 80);
    e.preventDefault();
  } else if (KEYMAP[e.key] !== undefined) {
    flushText();
    sendCtl({ type: "key", wid: focusWid(), keycode: KEYMAP[e.key] });
    e.preventDefault();
  }
});
document.addEventListener("keyup", () => {});

/* ---------------- 悬浮栏 ---------------- */
function setAudioUI(on) {
  S.audioEnabled = on;
  const btn = $("btnMute");
  btn.classList.toggle("on", !on);
  const icon = btn.querySelector("i");
  if (icon) icon.textContent = on ? "🎵" : "🔇";
  btn.title = on ? "音频传输开 (点击静音)" : "音频传输关 (点击恢复)";
  if (masterGain && actx) masterGain.gain.value = on ? 1 : 0;
}
/* 停止/开启投屏（远控设备端串流采集，不关端口；画面定格，重开后自动续流） */
function updateStreamUI(streaming) {
  const btn = $("btnStream");
  if (!btn) return;
  const icon = btn.querySelector("i"), label = btn.querySelector("span");
  if (streaming) {
    if (icon) icon.textContent = "⏹";
    if (label) label.textContent = "停止投屏";
    btn.classList.add("warn-on");
    btn.title = "停止投屏采集（省电，画面定格，可再点开启）";
  } else {
    if (icon) icon.textContent = "▶";
    if (label) label.textContent = "开启投屏";
    btn.classList.remove("warn-on");
    btn.title = "开启投屏采集";
  }
}
async function toggleStream() {
  const btn = $("btnStream");
  if (btn) btn.disabled = true;
  try {
    const cur = (S.lastStatus && typeof S.lastStatus.streaming === "boolean") ? S.lastStatus.streaming : null;
    const action = cur === null ? "toggle" : (cur ? "off" : "on");
    const r = await fetch(apiUrl("api/stream"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action }),
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.ok !== false) {
      toast(cur === true ? "⏹ 已停止投屏采集（端口保持，可远程点亮）"
        : cur === false ? "🎬 已开启投屏采集" : "投屏采集已切换");
      if (cur === true) showStreamOff(STREAM_STOPPED_MSG);
      else hideStreamOffRestore();
      pollStatus();
    } else toast("投屏切换失败: " + (j.error || r.status));
  } catch (e) { toast("投屏切换请求失败"); }
  finally { if (btn) btn.disabled = false; }
}
$("btnBack").onclick = () => sendCtl({ type: "click", button: "right" });
$("btnHome").onclick = () => sendCtl({ type: "click", button: "middle" });
$("btnRecents").onclick = () => sendCtl({ type: "key", keycode: 187 });
$("btnDesktop").onclick = toggleDesktop;
$("btnDeskHome").onclick = triggerDeskHome;
$("btnDeskTasks").onclick = showDeskTasksModal;
$("btnCloseTasks").onclick = () => $("tasksOverlay").classList.add("hide");
$("btnRefreshTasks").onclick = showDeskTasksModal;
$("pillDesk").onclick = toggleDesktop;
$("btnVolUp").onclick = () => sendCtl({ type: "key", keycode: 24 });
$("btnVolDown").onclick = () => sendCtl({ type: "key", keycode: 25 });
$("btnMute").onclick = () => { const next = !S.audioEnabled; if (sendCtl({ type: "audio", enabled: next })) setAudioUI(next); else toast("控制通道未连接"); };
$("btnPower").onclick = async () => {
  try {
    // ScreenSync-1：点击前先 GET 新鲜态（含手动电源键变更），不用 5s 轮询缓存算方向。
    let cur = S.lastStatus ? !!S.lastStatus.blackedOut : false;
    try {
      const sr = await fetch(apiUrl("api/screen"), { cache: "no-store" });
      if (sr.ok) {
        const sj = await sr.json().catch(() => ({}));
        if (sj && typeof sj.blackedOut === "boolean") {
          cur = !!sj.blackedOut;
          if (!S.lastStatus) S.lastStatus = {};
          S.lastStatus.blackedOut = cur;
        }
      }
    } catch (e) { /* 读失败回退轮询缓存 */ }
    const r = await fetch(apiUrl("api/screen"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: cur ? "on" : "off" }),
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.ok !== false) {
      if (j && typeof j.blackedOut === "boolean") {
        if (!S.lastStatus) S.lastStatus = {};
        S.lastStatus.blackedOut = !!j.blackedOut;
      }
      toast(cur ? "⏻ 已点亮屏幕" : "⏻ 已息屏挂机"); pollStatus();
    }
    else toast("屏幕切换失败: " + (j.error || j.detail || r.status));
  } catch (e) { toast("屏幕切换请求失败"); }
};
$("btnFull").onclick = () => {
  try {
    if (document.fullscreenElement) document.exitFullscreen();
    else stage.requestFullscreen();
  } catch (e) {}
};
$("btnKeys").onclick = () => { try { canvas.focus(); } catch (e) {} toast("键盘已聚焦，直接打字注入"); };
$("btnJpeg").onclick = () => {
  S.videoMode = (S.videoMode === "jpeg" ? "h264" : "jpeg");
  S.jpegBusy = false;
  // h264 时主画面由 Phase E 模块接管（画面在 #mainHost）：切 JPEG 必须放掉模块、改由 #canvas 显示，
  // 否则会「模块没了但落点还指着 #mainHost」→ 黑屏。切回 h264 则下次喂帧自动重建。
  if (S.videoMode === "jpeg") {
    try { if (mainPlayer) mainPlayer.close(); } catch (e) {}
    mainPlayer = null;
  }
  declareVideoMode();
  if (DESK.on) deskSyncCanvasHost(); else syncMirrorHost();
  toast(S.videoMode === "jpeg" ? "🎞 已切 JPEG 降级 (裸浏览器)" : "🎞 已切回 H264 (硬解路)");
};
$("btnReconnect").onclick = () => { hideStreamOffRestore(); showBoot("正在重连…"); connect(); };
$("btnStream").onclick = toggleStream;
/* 会话入口：连接两路 WS + 状态轮询 + 默认进入独立桌面。
 * 只出现在「兜底手动点进入控制台」这一条路（自动路径鉴权后直接开）。 */
function startSession() {
  connect();
  startStatusPoll();
  desktopAutoEnter(); // 不 await：画面先出来，桌面外壳随后顶上（失败会回退镜像）
}
$("btnEnter").onclick = () => { hideStreamOffRestore(); $("bootOverlay").classList.add("hide"); startSession(); };
$("btnStreamOn").onclick = async () => {
  const btn = $("btnStreamOn");
  btn.disabled = true;
  try {
    const r = await fetch(apiUrl("api/stream"), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "on" }),
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.ok !== false) {
      toast("🎬 已开启投屏采集，正在进入");
      hideStreamOffRestore();
      hideBoot();
      startSession();
    } else toast("开启投屏失败: " + (j.error || r.status));
  } catch (e) { toast("开启投屏请求失败"); }
  finally { btn.disabled = false; }
};

/* ---------------- 桌面小部件面板 ----------------
 * 手机端把桌面小部件渲染成 WebP 静帧，经 WS /ws/widgets 推送：
 *   下行二进制 [4字节大端 widgetId][WebP] → createImageBitmap → 画进该部件的 canvas，
 *   每帧画完立即回 widget-ack（服务端一 ack 一帧，漏发即断流）
 *   下行文本 widget-state(清单) / ack / pong
 *   上行文本 widget-list / widget-sync / widget-size / widget-input / widget-hide / widget-unbind / ping
 * 面板打开才连通道，关闭即断开（服务端随之停渲染）。位置尺寸纯前端布局，存 localStorage。 */
const WP_KEY = "blindcast.widgetLayout.v1";
const WP_HEAD_H = 24;                 // 标题栏高度，不计入服务端渲染尺寸
const WP_DEF_W = 320, WP_DEF_H = 200; // 无本地记录时的默认尺寸
const WP_MIN = 64, WP_MAX = 2048;     // 服务端限制 1..2048，下限 64 防误拖
const WP_DENSITY = 160;               // 1dp = 1px

const W = {
  ws: null, open: false, retry: 0, pingTimer: 0, sig: "",
  density: WP_DENSITY, state: null, list: new Map(), hidden: new Set(),
  menuFor: null, confirm: null,
};

function wpClampSize(v) { return Math.max(WP_MIN, Math.min(WP_MAX, Math.round(v || 0))); }
function wpSend(obj) {
  if (!W.ws || W.ws.readyState !== 1) return false;
  try { W.ws.send(JSON.stringify(obj)); return true; } catch (e) { return false; }
}
function wpSetState(cls, text) { $("wpState").className = "wp-state " + cls; $("wpState").textContent = text; }

/* ---- 布局持久化：{id:{x,y,w,h}}，w/h 是服务端渲染尺寸（不含标题栏） ---- */
function wpLoadLayout() {
  try { return JSON.parse(localStorage.getItem(WP_KEY) || "{}") || {}; } catch (e) { return {}; }
}
function wpSaveLayout() {
  const o = {};
  W.list.forEach(it => { o[it.id] = { x: Math.round(it.x), y: Math.round(it.y), w: it.w, h: it.h }; });
  try { localStorage.setItem(WP_KEY, JSON.stringify(o)); } catch (e) {}
}
function wpDropLayout() { try { localStorage.removeItem(WP_KEY); } catch (e) {} }

/* ---- 布局工具 ---- */
function wpSetBox(it, x, y, w, h, save) {
  if (typeof x === "number") it.x = Math.max(0, Math.round(x));
  if (typeof y === "number") it.y = Math.max(0, Math.round(y));
  if (typeof w === "number") it.w = wpClampSize(w);
  if (typeof h === "number") it.h = wpClampSize(h);
  it.el.style.left = it.x + "px"; it.el.style.top = it.y + "px";
  it.el.style.width = it.w + "px"; it.el.style.height = (it.h + WP_HEAD_H) + "px";
  it.el.classList.toggle("narrow", it.w < 190);
  wpBadge(it);
  if (save) wpSaveLayout();
}
function wpBadge(it) {
  it.badge.textContent = (it.stale ? "已卸载 " : it.live ? "● " : "○ ") + it.w + "×" + it.h;
}
/* 层随内容撑大，滚动容器才有真实可滚区域 */
function wpFitLayer() {
  const host = $("wpCanvas"), layer = $("wpLayer");
  let mx = 0, my = 0;
  W.list.forEach(it => { mx = Math.max(mx, it.x + it.w); my = Math.max(my, it.y + it.h + WP_HEAD_H); });
  layer.style.width = Math.max(host.clientWidth, mx + 24) + "px";
  layer.style.height = Math.max(host.clientHeight, my + 24) + "px";
}
function wpUpdateEmpty() {
  const el = $("wpEmpty");
  if (W.list.size) { el.classList.add("hide"); return; }
  el.classList.remove("hide");
  el.textContent = (W.ws && W.ws.readyState === 1)
    ? "手机上还没有绑定小部件 —— 在手机端打开 BlindCast 的「桌面小部件」页面添加"
    : "正在连接桌面小部件通道…";
}
function wpSelect(it) {
  W.list.forEach(o => { if (o !== it) o.el.classList.remove("sel"); });
  if (it) it.el.classList.add("sel");
}

/* ---- 清单 → DOM ---- */
function wpApplyState(st) {
  W.state = st;
  if (typeof st.density === "number") W.density = Math.max(80, Math.min(960, st.density));
  const arr = Array.isArray(st.widgets) ? st.widgets : [];
  const lay = wpLoadLayout(), seen = new Set();
  arr.forEach((m, i) => {
    if (!m || typeof m.id === "undefined" || W.hidden.has(m.id)) return;
    seen.add(m.id);
    wpEnsureItem(m, i, lay);
  });
  Array.from(W.list.keys()).forEach(id => { if (!seen.has(id)) wpRemoveItem(id); });
  wpUpdateEmpty(); wpFitLayer();
  // 收到清单即声明本会话要显示哪些部件、各多大；签名不变则不重复声明（防回声成环）
  const sig = JSON.stringify(arr.map(m => [m.id, !!m.stale, !!m.active, m.w, m.h]));
  if (W.sig !== sig) { W.sig = sig; wpSync(); }
}
function wpEnsureItem(m, idx, lay) {
  let it = W.list.get(m.id);
  if (!it) {
    const rec = lay[m.id] || {};
    // 无本地布局记录时用服务端给的自然尺寸（widget-state 的 w/h），别硬套 WP_DEF_*——
    // 实测 105x105 的部件套 320x200 会在画布里空掉一大片
    const w = wpClampSize(typeof rec.w === "number" ? rec.w : (m.w > 0 ? m.w : WP_DEF_W));
    const h = wpClampSize(typeof rec.h === "number" ? rec.h : (m.h > 0 ? m.h : WP_DEF_H));
    const x = typeof rec.x === "number" ? Math.max(0, rec.x) : 16 + (idx % 2) * (WP_DEF_W + 16);
    const y = typeof rec.y === "number" ? Math.max(0, rec.y)
                                        : 16 + Math.floor(idx / 2) * (WP_DEF_H + WP_HEAD_H + 16);
    const el = document.createElement("div");
    el.className = "wp-item";
    el.innerHTML = '<div class="wp-head"><span class="wp-name"></span><span class="wp-badge"></span></div>' +
                   '<canvas class="wp-cv"></canvas><div class="wp-rs" title="拖动缩放"></div>';
    it = {
      id: m.id, x: x, y: y, w: w, h: h, el: el, live: false, stale: false, active: false,
      head: el.querySelector(".wp-head"), name: el.querySelector(".wp-name"),
      badge: el.querySelector(".wp-badge"), cv: el.querySelector(".wp-cv"),
      rs: el.querySelector(".wp-rs"),
      touch: 0, downTs: 0, moving: null, resizing: null, lastMoveTs: 0, lastSizeTs: 0, sizeTimer: 0,
    };
    it.el.title = "拖动标题栏移动 · Alt+拖动图像移动 · 右下角缩放 · 图像左键=触控 · 滚轮=滑动 · 右键=菜单";
    $("wpLayer").appendChild(it.el);
    W.list.set(m.id, it);
    wpSetBox(it, x, y, w, h, false);
    wpBindItem(it);
    wpSaveLayout();
  }
  it.label = m.label || ("#" + m.id);
  it.stale = !!m.stale;
  it.active = !!m.active;
  if (it.stale) it.live = false;
  it.name.textContent = it.label;
  it.name.title = it.label + (m.provider ? " · " + m.provider : "");
  it.el.classList.toggle("stale", it.stale);
  wpBadge(it);
}
function wpRemoveItem(id) {
  const it = W.list.get(id);
  if (!it) return;
  if (it.sizeTimer) clearTimeout(it.sizeTimer);
  try { it.el.remove(); } catch (e) {}
  W.list.delete(id);
}
/* 声明本会话要显示的小部件与尺寸（服务端只渲染这个列表里的） */
function wpSync() {
  const widgets = [];
  W.list.forEach(it => widgets.push({ id: it.id, w: it.w, h: it.h }));
  return wpSend({ type: "widget-sync", density: W.density, widgets: widgets });
}

/* ---- 二进制帧：渲染 + ack（背压） ---- */
function wpOnFrame(buf) {
  const u8 = new Uint8Array(buf);
  if (u8.length < 5) return;
  const id = ((u8[0] << 24) | (u8[1] << 16) | (u8[2] << 8) | u8[3]) >>> 0;
  const it = W.list.get(id);
  if (!it) { wpSend({ type: "widget-ack", id: id }); return; } // 未声明过也要回执，别把服务端卡住
  const blob = new Blob([u8.subarray(4)], { type: "image/webp" });
  if (typeof createImageBitmap === "function") {
    createImageBitmap(blob).then(bmp => wpPaint(it, bmp)).catch(() => wpSend({ type: "widget-ack", id: id }));
  } else {
    // 极老浏览器回退：Image + objectURL（仍零依赖，与 JPEG 降级同路数）
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => { try { wpPaint(it, img); } finally { try { URL.revokeObjectURL(url); } catch (e) {} } };
    img.onerror = () => { wpSend({ type: "widget-ack", id: id }); try { URL.revokeObjectURL(url); } catch (e) {} };
    img.src = url;
  }
}
function wpPaint(it, src) {
  try {
    const cv = it.cv;
    const w = src.width || src.naturalWidth || it.w, h = src.height || src.naturalHeight || it.h;
    if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
    const c2 = cv.getContext("2d");
    c2.clearRect(0, 0, cv.width, cv.height);
    c2.drawImage(src, 0, 0, cv.width, cv.height);
    it.live = true;
    wpBadge(it);
  } finally {
    try { src.close && src.close(); } catch (e) {}
    wpSend({ type: "widget-ack", id: it.id }); // 背压：一帧一 ack
  }
}

/* ---- 坐标 / 上行输入 ---- */
function wpLocal(e, it) {
  const r = it.cv.getBoundingClientRect();
  const kx = r.width ? it.w / r.width : 1, ky = r.height ? it.h / r.height : 1;
  return {
    x: Math.max(0, Math.min(it.w - 1, Math.round((e.clientX - r.left) * kx))),
    y: Math.max(0, Math.min(it.h - 1, Math.round((e.clientY - r.top) * ky))),
  };
}
function wpInput(it, o) {
  // t = 相对本次手势 down 的毫秒偏移（服务端据此拼同一手势窗口的 downTime/eventTime，
  // 见 WidgetWsRoute.handleInput；传绝对 performance.now() 会被当成超长按）
  o.type = "widget-input"; o.id = it.id;
  o.t = Math.round(performance.now() - (it.downTs || performance.now()));
  if (o.a === "up" || o.a === "cancel") it.downTs = 0;
  wpSend(o);
}
/* 缩放手柄拖动时节流 ~200ms 发一次 widget-size */
function wpSendSize(it, force) {
  const now = performance.now(), gap = now - it.lastSizeTs;
  if (force || gap >= 200) {
    it.lastSizeTs = now;
    if (it.sizeTimer) { clearTimeout(it.sizeTimer); it.sizeTimer = 0; }
    wpSend({ type: "widget-size", id: it.id, w: it.w, h: it.h });
  } else if (!it.sizeTimer) {
    it.sizeTimer = setTimeout(() => { it.sizeTimer = 0; wpSendSize(it, true); }, 200 - gap);
  }
}

/* ---- 拖动 / 缩放 ---- */
function wpBeginMove(e, it) {
  wpSelect(it);
  it.moving = { pid: e.pointerId, sx: e.clientX, sy: e.clientY, x0: it.x, y0: it.y };
  try { it.el.setPointerCapture(e.pointerId); } catch (x) {}
}
function wpBeginResize(e, it) {
  wpSelect(it);
  it.resizing = { pid: e.pointerId, sx: e.clientX, sy: e.clientY, w0: it.w, h0: it.h };
  try { it.el.setPointerCapture(e.pointerId); } catch (x) {}
}
function wpEndGesture(e, it) {
  if (it.moving && it.moving.pid === e.pointerId) {
    it.moving = null;
    try { it.el.releasePointerCapture(e.pointerId); } catch (x) {}
    wpSaveLayout(); wpFitLayer();
  }
  if (it.resizing && it.resizing.pid === e.pointerId) {
    it.resizing = null;
    try { it.el.releasePointerCapture(e.pointerId); } catch (x) {}
    wpSaveLayout(); wpFitLayer();
    wpSendSize(it, true); // 收尾补一发最终尺寸
  }
}
function wpBindItem(it) {
  /* 标题栏 = 拖动移动 */
  it.head.addEventListener("pointerdown", e => {
    if (e.button !== 0) return;
    e.preventDefault();
    wpBeginMove(e, it);
  });
  /* 右下角手柄 = 缩放 */
  it.rs.addEventListener("pointerdown", e => {
    if (e.button !== 0) return;
    e.preventDefault();
    wpBeginResize(e, it);
  });
  it.el.addEventListener("pointermove", e => {
    if (it.moving && it.moving.pid === e.pointerId) {
      wpSetBox(it, it.moving.x0 + (e.clientX - it.moving.sx), it.moving.y0 + (e.clientY - it.moving.sy),
               null, null, false);
      return;
    }
    if (it.resizing && it.resizing.pid === e.pointerId) {
      wpSetBox(it, null, null, it.resizing.w0 + (e.clientX - it.resizing.sx),
               it.resizing.h0 + (e.clientY - it.resizing.sy), false);
      wpSendSize(it, false);
    }
  });
  it.el.addEventListener("pointerup", e => wpEndGesture(e, it));
  it.el.addEventListener("pointercancel", e => wpEndGesture(e, it));

  /* 图像 = 触控注入；Alt+拖动 / 还没出图的小部件 = 移动（此时注入无意义） */
  it.cv.addEventListener("pointerdown", e => {
    if (e.button !== 0) return;
    e.preventDefault();
    if (e.altKey || !it.live) { wpBeginMove(e, it); return; }
    wpSelect(it);
    it.touch = e.pointerId;
    it.downTs = performance.now(); // 手势起点，后续 move/up/cancel 的 t 以它为基准
    const p = wpLocal(e, it);
    wpInput(it, { x: p.x, y: p.y, a: "down" });
  });
  it.cv.addEventListener("pointermove", e => {
    if (it.touch !== e.pointerId) return;
    const now = performance.now();
    if (now - it.lastMoveTs < 16) return; // ~60Hz 节流
    it.lastMoveTs = now;
    const p = wpLocal(e, it);
    wpInput(it, { x: p.x, y: p.y, a: "move" });
  });
  const endTouch = (e, a) => {
    if (it.touch !== e.pointerId) return;
    it.touch = 0;
    const p = wpLocal(e, it);
    wpInput(it, { x: p.x, y: p.y, a: a });
  };
  it.cv.addEventListener("pointerup", e => endTouch(e, "up"));
  it.cv.addEventListener("pointercancel", e => endTouch(e, "cancel"));
  it.cv.addEventListener("pointerleave", e => endTouch(e, "cancel")); // 移出即取消
  it.cv.addEventListener("wheel", e => {
    e.preventDefault();
    const p = wpLocal(e, it);
    wpSend({ type: "widget-input", id: it.id, x: p.x, y: p.y, k: "scroll",
             dx: Math.round(e.deltaX), dy: Math.round(-e.deltaY) }); // dy 反向对齐触屏习惯
  }, { passive: false });
  it.el.addEventListener("contextmenu", e => { e.preventDefault(); wpOpenMenu(it, e.clientX, e.clientY); });
}

/* ---- 右键菜单 / 二次确认 ---- */
function wpOpenMenu(it, cx, cy) {
  const m = $("wpMenu");
  W.menuFor = it.id;
  m.classList.remove("hide");
  const host = $("widgetPanel").getBoundingClientRect();
  const mw = m.offsetWidth || 118, mh = m.offsetHeight || 76;
  m.style.left = Math.max(6, Math.min(host.width - mw - 6, cx - host.left)) + "px";
  m.style.top = Math.max(6, Math.min(host.height - mh - 6, cy - host.top)) + "px";
}
function wpCloseMenu() { $("wpMenu").classList.add("hide"); W.menuFor = null; }
function wpAsk(text, ok) {
  $("wpConfirmMsg").textContent = text;
  W.confirm = ok;
  $("wpConfirm").classList.remove("hide");
}
function wpAskClose() { W.confirm = null; $("wpConfirm").classList.add("hide"); }
document.addEventListener("pointerdown", e => {
  if (!$("wpMenu").contains(e.target)) wpCloseMenu();
}, true);
$("wpMenuHide").onclick = () => {
  const id = W.menuFor;
  wpCloseMenu();
  if (id === null) return;
  W.hidden.add(id);              // 本会话不再要它（手机侧绑定保留）
  wpSend({ type: "widget-hide", id: id });
  wpRemoveItem(id);
  wpSaveLayout(); wpFitLayer(); wpUpdateEmpty();
  toast("已隐藏该小部件（手机侧绑定保留）");
};
$("wpMenuUnbind").onclick = () => {
  const id = W.menuFor;
  wpCloseMenu();
  if (id === null) return;
  const it = W.list.get(id);
  wpAsk("解绑「" + (it ? it.label : "#" + id) + "」？会同时从手机端删除该小部件绑定，不可恢复。", () => {
    W.hidden.add(id);
    wpSend({ type: "widget-unbind", id: id });
    wpRemoveItem(id);
    wpSaveLayout(); wpFitLayer(); wpUpdateEmpty();
    toast("已解绑并从手机端删除");
  });
};
$("wpCancel").onclick = wpAskClose;
$("wpConfirmOk").onclick = () => { const f = W.confirm; wpAskClose(); if (f) f(); };

/* ---- 通道：ws://<host>/ws/widgets?token=…（复用 wsBase/token） ---- */
function wpConnect() {
  if (!W.open) return;
  if (W.ws && (W.ws.readyState === 0 || W.ws.readyState === 1)) return;
  wpClearRetry();
  let ws = null;
  try {
    ws = new WebSocket(wsBase() + "/ws/widgets" + (token ? "?token=" + encodeURIComponent(token) : ""));
  } catch (e) { wpScheduleRetry(); return; }
  ws.binaryType = "arraybuffer";
  W.ws = ws;
  wpSetState("", "连接中…");
  ws.onopen = () => {
    wpSetState("ok", "已连接");
    W.sig = "";                                  // 重连后强制重新声明
    wpSend({ type: "widget-list" });             // 重连后重新索取清单
    if (W.list.size || W.state) wpSync();        // 先按本地布局声明一次，服务端立刻开渲染
    wpStartPing();
    wpUpdateEmpty();
  };
  ws.onmessage = ev => {
    if (typeof ev.data === "string") wpOnText(ev.data);
    else if (ev.data) wpOnFrame(ev.data);
  };
  ws.onclose = () => {
    if (W.ws !== ws) return;
    W.ws = null;
    wpStopPing();
    wpSetState("bad", "未连接");
    wpUpdateEmpty();
    wpScheduleRetry();
  };
  ws.onerror = () => { try { ws.close(); } catch (e) {} };
}
function wpOnText(raw) {
  let m = null;
  try { m = JSON.parse(raw); } catch (e) { return; }
  if (!m || !m.type) return;
  if (m.type === "widget-state") wpApplyState(m);
  else if (m.type === "pong") { /* 心跳回执：通道存活即够，无需处理 */ }
  else if (m.type === "ack") { /* 命令回执：widget-sync 已生效 */ }
}
function wpDisconnect() {
  wpClearRetry(); wpStopPing();
  const ws = W.ws;
  W.ws = null;
  try { if (ws) ws.close(); } catch (e) {}
  wpSetState("", "未连接");
}
function wpScheduleRetry() {
  if (!W.open || W.retry) return;
  W.retry = setTimeout(() => { W.retry = 0; wpConnect(); }, 3000);
}
function wpClearRetry() { if (W.retry) clearTimeout(W.retry); W.retry = 0; }
function wpStartPing() {
  wpStopPing();
  W.pingTimer = setInterval(() => { if (W.ws && W.ws.readyState === 1) wpSend({ type: "ping" }); }, 2000);
}
function wpStopPing() { if (W.pingTimer) clearInterval(W.pingTimer); W.pingTimer = 0; }

/* ---- 开关面板 ---- */
function wpOpenPanel() {
  if (W.open) return;
  W.open = true;
  $("widgetPanel").classList.remove("hide");
  $("btnWidgets").classList.add("on");
  wpUpdateEmpty();
  wpFitLayer();
  wpConnect();
}
function wpClosePanel() {
  if (!W.open) return;
  W.open = false;
  $("widgetPanel").classList.add("hide");
  $("btnWidgets").classList.remove("on");
  wpCloseMenu(); wpAskClose();
  wpDisconnect();
}
$("btnWidgets").onclick = () => { if (W.open) wpClosePanel(); else wpOpenPanel(); };
$("wpClose").onclick = wpClosePanel;
$("wpRelayout").onclick = () => {
  wpDropLayout();
  let i = 0;
  W.list.forEach(it => {
    const x = 16 + (i % 2) * (WP_DEF_W + 16);
    const y = 16 + Math.floor(i / 2) * (WP_DEF_H + WP_HEAD_H + 16);
    i++;
    wpSetBox(it, x, y, WP_DEF_W, WP_DEF_H, false);
  });
  wpSaveLayout(); wpFitLayer(); wpSync();
  toast("已清空位置记录，小部件重新排列");
};
/* 跟随主连接：connect() 末尾调用，面板开着就一起重连 */
function wpFollowConnect() { if (W.open) wpConnect(); }
window.addEventListener("resize", () => { if (W.open) wpFitLayer(); });

/* ---------------- 配对码（手机端 9 字符一次性码换长期 token） ----------------
 * 成功后 token 走既有 bc_token，REST/WS 鉴权路径一律不动。 */
function pairNorm(v) { return (v || "").toUpperCase().replace(/[^0-9A-Z]/g, "").slice(0, 9); }
function pairFmt(d) { return d.length <= 4 ? d : d.slice(0, 4) + "-" + d.slice(4, 9); }
function authPaneInput() { return $("pairPane").classList.contains("hide") ? $("tokenInput") : $("pairInput"); }
function authShake() {
  $("authCard").classList.remove("shake");
  void $("authCard").offsetWidth;
  $("authCard").classList.add("shake");
}
function authTab(which) { // "pair" | "token"
  const pair = which !== "token";
  $("pairPane").classList.toggle("hide", !pair);
  $("tokenPane").classList.toggle("hide", pair);
  $("tabPair").classList.toggle("on", pair);
  $("tabToken").classList.toggle("on", !pair);
  $("authErr").textContent = "";
  authPaneInput().focus();
}
$("tabPair").onclick = () => authTab("pair");
$("tabToken").onclick = () => authTab("token");

/* 手机端客户端列表靠这个名字认设备，浏览器自报一个 */
function pairClientName() {
  const ua = navigator.userAgent || "";
  const os = /Android/i.test(ua) ? "Android" : /iPhone|iPad|iPod/i.test(ua) ? "iOS"
    : /Mac OS X/i.test(ua) ? "macOS" : /Windows/i.test(ua) ? "Windows" : /Linux/i.test(ua) ? "Linux" : "";
  const br = /Edg\//.test(ua) ? "Edge" : /OPR\//.test(ua) ? "Opera" : /Firefox\//.test(ua) ? "Firefox"
    : /Chrome\//.test(ua) ? "Chrome" : /Safari\//.test(ua) ? "Safari" : "浏览器";
  return os ? br + " / " + os : br;
}

/* 手抄常丢分隔符：输入即规整（大写、第 4 位后补 -），光标按有效字符数回位 */
$("pairInput").addEventListener("input", () => {
  const el = $("pairInput"), kept = pairNorm(el.value.slice(0, el.selectionStart || 0)).length;
  el.value = pairFmt(pairNorm(el.value));
  const at = kept + (kept > 4 ? 1 : 0);
  try { el.setSelectionRange(at, at); } catch (e) {}
});

/* 429 退避：按服务端 retryAfterMs 倒计时，期间禁用按钮 */
let pairCdTimer = 0;
function pairCooldown(ms) {
  clearInterval(pairCdTimer);
  let left = Math.max(1, Math.ceil((ms || 0) / 1000));
  const btn = $("btnPair");
  const paint = () => {
    if (left <= 0) {
      clearInterval(pairCdTimer); pairCdTimer = 0;
      btn.disabled = false; btn.textContent = "连接"; $("authErr").textContent = "";
      return;
    }
    btn.disabled = true; btn.textContent = "等待 " + left + "s";
    $("authErr").textContent = "尝试过于频繁，请等待 " + left + " 秒";
    left--;
  };
  paint();
  pairCdTimer = setInterval(paint, 1000);
}

async function submitPair() {
  const err = m => { $("authErr").textContent = m; };
  const code = pairNorm($("pairInput").value);
  if (code.length !== 9) { err("配对码为 9 位字符，请对照手机重新输入"); return; }
  if ($("btnPair").disabled) return;
  $("btnPair").disabled = true;
  err("校验中…");
  let r = null;
  try {
    r = await fetch(deviceUrl("api/pair"), {
      method: "POST", cache: "no-store", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ code: pairFmt(code), name: pairClientName() })
    });
  } catch (e) {
    $("btnPair").disabled = false;
    err("连接失败，检查手机是否在线"); authShake();
    return;
  }
  const j = await r.json().catch(() => ({}));
  if (r.ok && j.token) {
    rememberToken(j.token);
    hideAuth();
    if (await gateEnter("配对成功，正在进入")) { hideBoot(); startSession(); }
    return;
  }
  $("btnPair").disabled = false;
  if (r.status === 429) { pairCooldown(j.retryAfterMs); return; } // 倒计时自己管按钮状态
  err(r.status === 401 ? "配对码无效或已过期，请在手机上重新生成"
    : r.status === 503 ? "配对设备数量已达上限，请在手机上吊销一些设备"
    : r.status === 400 ? "配对码格式不正确，请对照手机重新输入"
    : r.status === 404 ? "手机端版本不支持配对码，请改用访问口令"
    : "配对失败: " + (j.error || r.status));
  authShake();
}
$("btnPair").onclick = submitPair;
$("pairInput").addEventListener("keydown", e => { if (e.key === "Enter") submitPair(); });

/* 地址栏里的配对码用完就抹：避免截图转发泄露，也避免刷新重放 */
function dropPairParam() {
  if (!qsPair) return;
  try {
    const u = new URL(location.href);
    u.searchParams.delete("pair");
    history.replaceState(null, "", u.pathname + u.search + u.hash);
  } catch (e) {}
}

/* ---------------- 鉴权提交 ---------------- */
async function submitAuth() {
  const t = $("tokenInput").value.trim();
  if (!t) { $("authErr").textContent = "请输入 Token"; return; }
  $("authErr").textContent = "校验中…";
  if (await apiVerify(t)) {
    rememberToken(t);
    hideAuth();
    if (await gateEnter("鉴权通过，正在进入")) { hideBoot(); startSession(); }
  } else {
    $("authErr").textContent = "Token 错误，请重试";
    authShake();
  }
}
$("btnAuth").onclick = submitAuth;
$("tokenInput").addEventListener("keydown", e => { if (e.key === "Enter") submitAuth(); });

/* ---------------- 启动 ----------------
 * 鉴权一过就直接开会话（默认目标 = 独立桌面），不再要求「进入控制台」+「独立桌面」两次点击；
 * 只有投屏采集起不来时才退化成手动入口。 */
async function autoEnter() {
  if (await gateEnter("正在进入控制台…")) { hideBoot(); startSession(); }
}
(async function boot() {
  fitCanvas();
  let st = null;
  try { st = await apiStatus(); }
  catch (e) { showBoot("无法连接服务，检查 http://&lt;手机IP&gt;:8888"); return; }
  if (!st.authRequired) {
    if (qsToken) rememberToken(qsToken); // 免密模式也记住URL携带的token(供WS/REST透传)
    dropPairParam(); // 免密模式配对码无用，别留在地址栏
    await autoEnter();
    return;
  }
  // 设密模式: ?token= > localStorage > 弹窗
  if (qsToken && await apiVerify(qsToken)) { rememberToken(qsToken); dropPairParam(); await autoEnter(); return; }
  if (token && await apiVerify(token)) { dropPairParam(); await autoEnter(); return; }
  showAuth("");
  if (!qsPair) return;
  // 二维码链接带入的配对码：填好直接提交一次，成败都要从地址栏抹掉
  $("pairInput").value = pairFmt(pairNorm(qsPair));
  try { await submitPair(); } finally { dropPairParam(); }
})();
